INSERT INTO `landing_blocks` (`id`,`section`,`sort`,`title`,`subtitle`,`body`,`image`,`icon`,`meta`,`active`) VALUES
(1,'problema',1,'Se pierde el hilo',NULL,'La cotización queda enterrada en un chat. Nadie sabe si el cliente la aprobó, la rechazó o simplemente la olvidó.',NULL,NULL,NULL,1),
(2,'problema',2,'Precios distintos',NULL,'Cada vendedor arma su cotización en Excel con su propio formato y su propio criterio de descuento.',NULL,NULL,NULL,1),
(3,'problema',3,'Sin catálogo',NULL,'El cliente no puede ver qué vende usted: tiene que preguntar por cada código, uno por uno.',NULL,NULL,NULL,1),
(4,'problema',4,'Cero medición',NULL,'No sabe cuánto cotizó este mes, cuánto ganó, ni por qué perdió las que perdió.',NULL,NULL,NULL,1),
(5,'paso',1,'Suba su catálogo',NULL,'Importe el CSV que ya exportó de WooCommerce o use la plantilla de Excel: categorías, códigos, medidas y fotos.',NULL,NULL,NULL,1),
(6,'paso',2,'El cliente cotiza solo',NULL,'Busca por código o medida, arma su lista y envía la solicitud con sus datos. Sin registro, sin fricción.',NULL,NULL,NULL,1),
(7,'paso',3,'Usted cierra la venta',NULL,'Recibe la solicitud en su tablero, ajusta precios, genera el PDF y lo envía por correo y WhatsApp en un clic.',NULL,NULL,NULL,1),
(8,'beneficio',1,'Catálogo con atributos técnicos',NULL,'Defina material, medida, norma o aplicación. El cliente filtra como en un catálogo de fabricante.',NULL,NULL,NULL,1),
(9,'beneficio',2,'Precios que usted controla',NULL,'Ocúltelos, muéstrelos a todos o solo a clientes. Listas de precio por tipo de cliente.',NULL,NULL,NULL,1),
(10,'beneficio',3,'PDF de lujo con su marca',NULL,'Su logo, sus colores, su firma y un QR que lleva al seguimiento en línea.',NULL,NULL,NULL,1),
(11,'beneficio',4,'Kanban con semáforo',NULL,'Verde, amarillo y rojo según los días sin contactar al cliente. Nada se enfría.',NULL,NULL,NULL,1),
(12,'beneficio',5,'Recordatorios automáticos',NULL,'El sistema le avisa cuando una cotización lleva días sin respuesta.',NULL,NULL,NULL,1),
(13,'beneficio',6,'Reportes que sí usa',NULL,'Monto cotizado, ganado, conversión, ranking de vendedores y motivos de pérdida.',NULL,NULL,NULL,1),
(14,'testimonio',1,'Roberto Pérez','Gerente general · Industrial Pérez','Antes cotizábamos por WhatsApp y perdíamos el rastro. Hoy el cliente entra, arma su lista y nosotros solo confirmamos precios. Bajamos el tiempo de respuesta de dos días a veinte minutos.',NULL,NULL,NULL,1),
(15,'testimonio',2,'Mónica Roca','Directora comercial · Uniformes Roca','El catálogo con tallas y el PDF con nuestro logo nos hicieron ver más grandes de lo que somos. Los clientes corporativos nos toman más en serio.',NULL,NULL,NULL,1),
(16,'testimonio',3,'Ana Lucía Ramírez','Asesora técnica · Industrial Pérez','El tablero con semáforo es lo que más uso. Si una cotización se pone en rojo ya sé que tengo que llamar hoy mismo.',NULL,NULL,NULL,1);
