-- =====================================================================
--  CotizaPro B2B · datos de demostración
--  Empresas: Industrial Pérez, S.A. y Uniformes Roca
--  Se importa DESPUÉS de database.sql (el instalador lo hace solo).
-- =====================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

-- companies (2 filas)
DELETE FROM `companies`;

-- users (7 filas)
DELETE FROM `users` WHERE `role` <> 'superadmin';

-- brands (8 filas)
DELETE FROM `brands`;

-- categories (12 filas)
DELETE FROM `categories`;

-- attribute_defs (8 filas)
DELETE FROM `attribute_defs`;

-- products (51 filas)
DELETE FROM `products`;

-- product_images (51 filas)
DELETE FROM `product_images`;

-- product_attributes (199 filas)
DELETE FROM `product_attributes`;

-- product_documents (1 filas)
DELETE FROM `product_documents`;

-- price_lists (5 filas)
DELETE FROM `price_lists`;

-- product_prices (11 filas)
DELETE FROM `product_prices`;

-- customers (23 filas)
DELETE FROM `customers`;

-- customer_contacts (20 filas)
DELETE FROM `customer_contacts`;

-- quotes (39 filas)
DELETE FROM `quotes`;

-- quote_items (147 filas)
DELETE FROM `quote_items`;

-- quote_events (168 filas)
DELETE FROM `quote_events`;

-- landing_blocks (16 filas)
DELETE FROM `landing_blocks`;

-- Asigna los planes por código (los ids dependen de la instalación).
UPDATE `companies` SET `plan_id` = (SELECT id FROM plans WHERE code = 'pro' LIMIT 1) WHERE slug = 'industrial-perez';
UPDATE `companies` SET `plan_id` = (SELECT id FROM plans WHERE code = 'basico' LIMIT 1) WHERE slug = 'uniformes-roca';

-- Empresa que se muestra como demostración en la landing.
  ON DUPLICATE KEY UPDATE `value` = VALUES(`value`);
  ON DUPLICATE KEY UPDATE `value` = `value`;
  ON DUPLICATE KEY UPDATE `value` = `value`;

SET FOREIGN_KEY_CHECKS = 1;
